SELECT t.test_run_id, MIN(t.generated_at) AS first_gen, MAX(t.generated_at) AS last_gen, COUNT(*) AS n_signals, COUNT(DISTINCT t.symbol) AS n_symbols, SUM(t.source_signal_id IN (156723,159408,165412,167668,171589,176710)) AS frozen_entry_signals FROM trade_signal_test t WHERE t.generated_at BETWEEN '2026-10-11 17:00:00' AND '2026-10-12 12:00:00' GROUP BY t.test_run_id ORDER BY frozen_entry_signals DESC, t.test_run_id DESC LIMIT 20